'use client';

import { useId, useRef, useState } from 'react';
import type { KeyboardEvent, ReactNode } from 'react';
import './service-showcase.css';

export interface ServiceShowcaseItem {
  id: string;
  title: string;
  description: string;
  capabilities: string[];
  /** Decorative media without nested controls; provide a separate href for the call to action. */
  media: ReactNode;
  href?: string;
  linkLabel?: string;
}

export interface ServiceShowcaseProps {
  items: ServiceShowcaseItem[];
  title?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  className?: string;
}

/** An editorial services section with one accessible tab panel per offering. */
export function ServiceShowcase({ items, title = 'How we can help', defaultValue, onValueChange, className = '' }: ServiceShowcaseProps) {
  const instance = useId();
  const [selected, setSelected] = useState(defaultValue ?? items[0]?.id);
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const activeId = items.some(item => item.id === selected) ? selected : items[0]?.id;

  function select(index: number, focus = false) {
    const item = items[index];
    if (!item) return;
    if (item.id !== activeId) {
      setSelected(item.id);
      onValueChange?.(item.id);
    }
    if (focus) buttons.current[index]?.focus();
  }

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next: number | undefined;
    if (event.key === 'ArrowDown') next = (index + 1) % items.length;
    if (event.key === 'ArrowUp') next = (index - 1 + items.length) % items.length;
    if (event.key === 'Home') next = 0;
    if (event.key === 'End') next = items.length - 1;
    if (next === undefined) return;
    event.preventDefault();
    select(next, true);
  }

  if (!items.length) return null;

  return <section className={`ac-service-showcase ${className}`.trim()} aria-labelledby={`${instance}-heading`}>
    <header className="ac-service-showcase-header"><span aria-hidden="true">OUR EXPERTISE</span><h2 id={`${instance}-heading`}>{title}</h2></header>
    <div className="ac-service-showcase-layout">
      <div className="ac-service-showcase-tabs" role="tablist" aria-label={title} aria-orientation="vertical">
        {items.map((item, index) => <button ref={node => { buttons.current[index] = node; }} type="button" role="tab" id={`${instance}-tab-${index}`} aria-selected={item.id === activeId} aria-controls={`${instance}-panel-${index}`} tabIndex={item.id === activeId ? 0 : -1} className="ac-service-showcase-tab" key={item.id} onClick={() => select(index)} onKeyDown={event => onKeyDown(event, index)}><span className="ac-service-showcase-number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span><span>{item.title}</span><span className="ac-service-showcase-arrow" aria-hidden="true">↗</span></button>)}
      </div>
      <div className="ac-service-showcase-panels">
        {items.map((item, index) => <div role="tabpanel" id={`${instance}-panel-${index}`} aria-labelledby={`${instance}-tab-${index}`} tabIndex={0} hidden={item.id !== activeId} className="ac-service-showcase-panel" key={item.id}>
          <div className="ac-service-showcase-media" aria-hidden="true" ref={node => { if (node) node.setAttribute('inert', ''); }}>{item.media}</div>
          <div className="ac-service-showcase-copy"><p>{item.description}</p><ul className="ac-service-showcase-capabilities" aria-label={`${item.title} capabilities`}>{item.capabilities.map((capability, capabilityIndex) => <li key={`${capability}-${capabilityIndex}`}>{capability}</li>)}</ul>{item.href && <a className="ac-service-showcase-link" href={item.href}>{item.linkLabel ?? `Explore ${item.title}`}<span aria-hidden="true">↗</span></a>}</div>
        </div>)}
      </div>
    </div>
  </section>;
}

.ac-service-showcase{--ac-service-surface:var(--ac-service-theme-surface, #f0efe8);--ac-service-ink:var(--ac-service-theme-ink, #25281f);--ac-service-muted:var(--ac-service-theme-muted, #697060);--ac-service-accent:#3b4930;--ac-service-line:var(--ac-service-theme-line, #25281f26);--ac-service-font:inherit;box-sizing:border-box;container-type:inline-size;width:100%;padding:clamp(20px,5cqw,48px);background:var(--ac-service-surface);color:var(--ac-service-ink);font-family:var(--ac-service-font)}
.ac-service-showcase *{box-sizing:border-box}.ac-service-showcase-header{display:flex;flex-wrap:wrap;gap:18px 32px;align-items:baseline;justify-content:space-between;margin-bottom:34px}.ac-service-showcase-header>span{font-size:10px;font-weight:600;letter-spacing:.13em}.ac-service-showcase-header h2{margin:0;font-size:clamp(25px,4.5cqw,42px);font-weight:500;line-height:1.08;letter-spacing:-.05em}.ac-service-showcase-layout{display:grid;grid-template-columns:minmax(150px,.8fr) minmax(0,1.5fr);gap:clamp(24px,5cqw,64px);align-items:start}.ac-service-showcase-tabs{display:flex;flex-direction:column;border-top:1px solid var(--ac-service-line)}
.ac-service-showcase-tab{appearance:none;display:flex;gap:12px;align-items:center;text-align:left;width:100%;min-height:66px;margin:0;padding:18px 0;border:0;border-bottom:1px solid var(--ac-service-line);border-radius:0;background:transparent;color:var(--ac-service-muted);font:inherit;font-size:clamp(17px,2.6cqw,25px);line-height:1.2;letter-spacing:-.045em;cursor:pointer;transition:color .2s,padding .2s}.ac-service-showcase-number{align-self:center;flex:0 0 auto;font-size:10px;letter-spacing:0;font-weight:400;opacity:.7}.ac-service-showcase-arrow{margin-left:auto;font-size:24px;opacity:0;transform:translate(-5px,5px);transition:opacity .2s,transform .2s}.ac-service-showcase-tab[aria-selected=true]{color:var(--ac-service-ink);padding-left:8px}.ac-service-showcase-tab[aria-selected=true] .ac-service-showcase-arrow{opacity:1;transform:translate(0,0)}.ac-service-showcase-tab:hover{color:var(--ac-service-ink)}.ac-service-showcase :is(button,a,[role=tabpanel]):focus-visible{outline:2px solid var(--ac-service-accent);outline-offset:5px}
.ac-service-showcase-panel[hidden]{display:none}.ac-service-showcase-panel:not([hidden]){animation:ac-service-arrive .32s ease-out both}.ac-service-showcase-media{width:100%;aspect-ratio:16/9;overflow:hidden;background:var(--ac-service-line);border-radius:3px;pointer-events:none}.ac-service-showcase-media>img,.ac-service-showcase-media>video{width:100%;height:100%;display:block;object-fit:cover}.ac-service-showcase-copy{padding-top:20px}.ac-service-showcase-copy>p{margin:0;max-width:46ch;font-size:clamp(14px,2.2cqw,18px);line-height:1.55;letter-spacing:-.02em}.ac-service-showcase-capabilities{list-style:none;display:flex;flex-wrap:wrap;gap:7px;margin:17px 0 0;padding:0}.ac-service-showcase-capabilities li{padding:7px 10px;border:1px solid var(--ac-service-line);border-radius:99px;font-size:10px;line-height:1.2;color:var(--ac-service-muted)}.ac-service-showcase-link{display:inline-flex;align-items:center;gap:24px;margin-top:23px;padding:3px 0 7px;border-bottom:1px solid currentColor;color:var(--ac-service-ink);font-size:12px;line-height:1.5;text-decoration:none}.ac-service-showcase-link>span{font-size:18px;transition:transform .2s}.ac-service-showcase-link:hover>span{transform:translate(3px,-3px)}
@container (max-width:500px){.ac-service-showcase-layout{grid-template-columns:minmax(0,1fr);gap:22px}.ac-service-showcase-header{display:block;margin-bottom:25px}.ac-service-showcase-header h2{margin-top:11px}.ac-service-showcase-tab{min-height:51px;padding-top:13px;padding-bottom:13px;font-size:20px}.ac-service-showcase-media{aspect-ratio:16/8}.ac-service-showcase-copy{padding-top:17px}}
@keyframes ac-service-arrive{from{opacity:.4;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.ac-service-showcase-panel:not([hidden]){animation:none}.ac-service-showcase-tab,.ac-service-showcase-arrow,.ac-service-showcase-link>span{transition:none}}

/* Neutral surfaces follow an explicit page theme; artwork and accents keep their palette. */
:where([data-theme="light"]) .ac-service-showcase {
  --ac-service-theme-ink: #202722;
  --ac-service-theme-line: #d7ded4;
  --ac-service-theme-muted: #687269;
  --ac-service-theme-surface: #fafbf8;
  color-scheme: light;
}
:where([data-theme="dark"], .dark) .ac-service-showcase {
  --ac-service-theme-ink: #edf2eb;
  --ac-service-theme-line: #3d483e;
  --ac-service-theme-muted: #a7b3a3;
  --ac-service-theme-surface: #191e1b;
  color-scheme: dark;
}
:where([data-theme="dark"], .dark) .ac-service-showcase :is(button, a, [role=tabpanel]):focus-visible { outline-color: var(--ac-service-ink); }
